#!/usr/bin/env node
// DEC-P10-001 — discovers workspace.manifest.json under packages/workspaces/
// Emits host + SDK registry files. Run: pnpm run generate:workspace-registry
import { readFileSync, readdirSync, writeFileSync, existsSync } from "node:fs";
import path from "node:path";
const { dirname, join } = path;
import { fileURLToPath, pathToFileURL } from "node:url";

const REPO_ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const DEFAULT_WORKSPACES_DIR = join(REPO_ROOT, "packages/workspaces");

const BANNER = `/**
 * AUTO-GENERATED by scripts/generate-workspace-registry.mjs — DO NOT EDIT.
 * Source: workspace.manifest.json per workspace package.
 * Regenerate: pnpm run generate:workspace-registry
 */
`;

/**
 * @param {string} [workspacesDir]
 */
export function discoverManifests(workspacesDir = DEFAULT_WORKSPACES_DIR) {
  const manifests = [];
  for (const ent of readdirSync(workspacesDir, { withFileTypes: true })) {
    if (!ent.isDirectory()) continue;
    const manifestPath = join(workspacesDir, ent.name, "workspace.manifest.json");
    if (!existsSync(manifestPath)) continue;
    const raw = JSON.parse(readFileSync(manifestPath, "utf8"));
    for (const key of ["id", "version", "package", "workspaceTypes", "plugin"]) {
      if (raw[key] === undefined) {
        throw new Error(`${manifestPath}: missing required field "${key}"`);
      }
    }
    manifests.push(raw);
  }
  if (manifests.length === 0) {
    throw new Error(`No workspace.manifest.json found under ${workspacesDir}`);
  }
  return manifests.sort((a, b) => a.id.localeCompare(b.id));
}

function importSpecifier(pkg, entry) {
  if (entry === ".") return pkg;
  if (entry.startsWith("./")) return `${pkg}/${entry.slice(2)}`;
  return `${pkg}/${entry}`;
}

/**
 * Host Prisma/outbox adapters for manifest `events[]` — extend when adding plugins.
 * @type {Readonly<Record<string, { importPath: string; export: string }>>}
 */
const HOST_OUTBOX_SIDE_EFFECT_ADAPTERS = Object.freeze({
  "denali:TourCreated": {
    importPath: "../denali-finance/tour-created-finance-side-effect",
    export: "runTourCreatedFinanceSideEffect",
  },
});

export function generateTourWriteBindings(manifests) {
  const withTourWrite = manifests.filter((m) => m.tourWrite !== undefined);
  if (withTourWrite.length === 0) {
    return `${BANNER}
export const WORKSPACE_TOUR_WRITE_BINDINGS = [] as const;
`;
  }

  /** @type {Set<string>} */
  const importLines = new Set();
  /** @type {string[]} */
  const bindingBlocks = [];

  for (const m of withTourWrite) {
    const tw = m.tourWrite;
    const toursSpec = importSpecifier(m.package, tw.module);
    importLines.add(`import { ${tw.workspaceTypeExport} } from "${m.package}";`);
    importLines.add(
      `import { ${tw.mergeExport}, ${tw.publishGateExport}, ${tw.publishSurfaceExport} } from "${toursSpec}";`
    );
    bindingBlocks.push(`  {
    workspaceType: ${tw.workspaceTypeExport},
    mergeCanonicalPatch: ${tw.mergeExport},
    publishFieldGate: ${tw.publishGateExport},
    publishOwnerSurface: ${tw.publishSurfaceExport},
  },`);
  }

  return `${BANNER}
${[...importLines].join("\n")}

export const WORKSPACE_TOUR_WRITE_BINDINGS = [
${bindingBlocks.join("\n")}
] as const;
`;
}

export function generateOutboxSideEffects(manifests) {
  /** @type {{ workspaceTypes: string[]; eventType: string; export: string; importPath: string }[]} */
  const rows = [];
  /** @type {Map<string, Set<string>>} */
  const importsByPath = new Map();

  for (const m of manifests) {
    if (!Array.isArray(m.events) || m.events.length === 0) continue;
    for (const ev of m.events) {
      const key = `${m.id}:${ev.eventType}`;
      const adapter = HOST_OUTBOX_SIDE_EFFECT_ADAPTERS[key];
      if (adapter === undefined) {
        throw new Error(
          `workspace.manifest.json ${m.id} event ${ev.eventType}: register host adapter in HOST_OUTBOX_SIDE_EFFECT_ADAPTERS`
        );
      }
      const workspaceTypes = ev.workspaceTypes ?? m.workspaceTypes;
      if (!importsByPath.has(adapter.importPath)) {
        importsByPath.set(adapter.importPath, new Set());
      }
      importsByPath.get(adapter.importPath).add(adapter.export);
      rows.push({
        workspaceTypes,
        eventType: ev.eventType,
        export: adapter.export,
        importPath: adapter.importPath,
      });
    }
  }

  if (rows.length === 0) {
    return `${BANNER}
import type { WorkspaceOutboxPublishedRow } from "./workspace-outbox-row-context";

export const WORKSPACE_OUTBOX_SIDE_EFFECT_BINDINGS = [] as const;
`;
  }

  const importLines = [...importsByPath.entries()].map(([importPath, exports]) => {
    return `import { ${[...exports].sort().join(", ")} } from "${importPath}";`;
  });

  const bindingBlocks = rows.map(
    (row) => `  {
    workspaceTypes: ${JSON.stringify(row.workspaceTypes)},
    eventType: ${JSON.stringify(row.eventType)},
    run: ${row.export},
  },`
  );

  return `${BANNER}
import type { WorkspaceOutboxPublishedRow } from "./workspace-outbox-row-context";
${importLines.join("\n")}

export type WorkspaceOutboxSideEffectRunner = (
  row: WorkspaceOutboxPublishedRow
) => Promise<void | boolean>;

export const WORKSPACE_OUTBOX_SIDE_EFFECT_BINDINGS: readonly {
  readonly workspaceTypes: readonly string[];
  readonly eventType: string;
  readonly run: WorkspaceOutboxSideEffectRunner;
}[] = [
${bindingBlocks.join("\n")}
];
`;
}

export function generateSdkBindings(manifests) {
  const lines = manifests.flatMap((m) =>
    m.workspaceTypes.map(
      (wt) => `  { workspaceType: ${JSON.stringify(wt)}, pluginId: ${JSON.stringify(m.id)} },`
    )
  );

  return `${BANNER}
import type { WorkspacePluginId } from "./workspace-plugin-id";
import type { WorkspaceTypeId } from "./workspace-type";

export const WORKSPACE_MANIFEST_BINDINGS: readonly {
  readonly workspaceType: WorkspaceTypeId;
  readonly pluginId: WorkspacePluginId;
}[] = [
${lines.join("\n")}
];
`;
}

export function generateApiRegistry(manifests) {
  const importLines = manifests.map((m) => {
    const spec = importSpecifier(m.package, m.plugin.entry);
    return `import { ${m.plugin.export} } from "${spec}";`;
  });

  const pluginCalls = manifests.map((m) => `    ${m.plugin.export}(),`).join("\n");

  return `${BANNER}
import type { WorkspacePlugin } from "@app-tour/workspace-sdk";
${importLines.join("\n")}

export function listApiWorkspacePluginsFromManifest(): readonly WorkspacePlugin[] {
  return [
${pluginCalls}
  ];
}
`;
}

export function generateWebLoaders(manifests) {
  const cases = manifests
    .map((m) => {
      const web = m.web ?? m.plugin;
      const spec = importSpecifier(m.package, web.entry);
      return `    case "${m.id}": {
      const mod = await import("${spec}");
      return mod.${web.export}();
    }`;
    })
    .join("\n");

  return `${BANNER}
import type { WorkspacePlugin } from "@app-tour/workspace-sdk";

const pluginLoadCache = new Map<string, Promise<WorkspacePlugin>>();

export async function loadWorkspacePluginByIdFromRegistry(
  pluginId: string
): Promise<WorkspacePlugin> {
  const cached = pluginLoadCache.get(pluginId);
  if (cached) return cached;

  const loadPromise = (async () => {
    switch (pluginId) {
${cases}
      default:
        throw new Error(\`WORKSPACE_PLUGIN_NOT_FOUND:\${pluginId}\`);
    }
  })();

  pluginLoadCache.set(pluginId, loadPromise);
  return loadPromise;
}
`;
}

export function generateAllOutputs(manifests) {
  return {
    sdk: generateSdkBindings(manifests),
    api: generateApiRegistry(manifests),
    web: generateWebLoaders(manifests),
    tourWrite: generateTourWriteBindings(manifests),
    outbox: generateOutboxSideEffects(manifests),
  };
}

const OUTPUT_PATHS = {
  sdk: join(REPO_ROOT, "packages/workspace-sdk/src/plugin/workspace-manifest-bindings.generated.ts"),
  api: join(REPO_ROOT, "apps/api/src/workspace/workspace-plugin-registry.generated.ts"),
  web: join(REPO_ROOT, "apps/web/src/bootstrap/workspace-plugin-loaders.generated.ts"),
  tourWrite: join(REPO_ROOT, "apps/api/src/tours/workspace-tour-write-bindings.generated.ts"),
  outbox: join(REPO_ROOT, "apps/api/src/workspace/workspace-outbox-side-effects.generated.ts"),
};

function readOutputs() {
  return Object.fromEntries(
    Object.entries(OUTPUT_PATHS).map(([key, path]) => [key, readFileSync(path, "utf8")])
  );
}

function main() {
  const checkOnly = process.argv.includes("--check");
  const manifests = discoverManifests();
  const generated = generateAllOutputs(manifests);

  if (checkOnly) {
    const onDisk = readOutputs();
    const mismatches = [];
    for (const key of ["sdk", "api", "web", "tourWrite", "outbox"]) {
      if (onDisk[key] !== generated[key]) {
        mismatches.push(OUTPUT_PATHS[key]);
      }
    }
    if (mismatches.length > 0) {
      console.error("generate:workspace-registry --check: FAIL (stale generated files)");
      for (const p of mismatches) console.error(`  ${p}`);
      console.error("Run: pnpm run generate:workspace-registry");
      process.exit(1);
    }
    console.log(
      `generate:workspace-registry --check: PASS (${manifests.length} manifest(s))`
    );
    return;
  }

  writeFileSync(OUTPUT_PATHS.sdk, generated.sdk);
  writeFileSync(OUTPUT_PATHS.api, generated.api);
  writeFileSync(OUTPUT_PATHS.web, generated.web);
  writeFileSync(OUTPUT_PATHS.tourWrite, generated.tourWrite);
  writeFileSync(OUTPUT_PATHS.outbox, generated.outbox);

  console.log(
    `generate:workspace-registry — ${manifests.length} manifest(s) → SDK, API, web, tour-write, outbox`
  );
}

const isMain =
  process.argv[1] !== undefined &&
  import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href;
if (isMain) {
  main();
}
